import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

import 'package:flutter_test/flutter_test.dart';
import 'package:keytitan/passwords.dart';
import 'package:keytitan/sensitive.dart';
import 'package:keytitan/vault_format.dart';

Uint8List _hex(String text) => Uint8List.fromList([
  for (var i = 0; i < text.length; i += 2)
    int.parse(text.substring(i, i + 2), radix: 16),
]);

void main() {
  test(
    'KTN4 and both field formats accept independent Unicode vectors',
    () async {
      // Generated by Python's cryptography implementation, not KeyTitan's codec.
      final vector =
          jsonDecode(
                await File(
                  'test/fixtures/ktn4_compatibility.json',
                ).readAsString(),
              )
              as Map<String, dynamic>;
      final password = utf8.encode(vector['password'] as String);
      final dek = _hex(vector['vaultKeyHex'] as String);
      final decoded = await KeyTitanVaultCodec.decryptV4(
        _hex(vector['vaultHex'] as String),
        password,
      );
      expect(decoded, isNotNull);
      try {
        expect(decoded!.vaultKey, dek);
        expect(decoded.sqliteBytes, _hex(vector['sqliteHex'] as String));
        expect(decoded.revision, vector['revision']);
        expect(
          await keyTitanPass.hdecrypt(dek, vector['v2Ciphertext'] as String),
          vector['v2Plaintext'],
        );
        expect(
          await keyTitanPass.hdecrypt(
            password,
            vector['v1Ciphertext'] as String,
          ),
          vector['v1Plaintext'],
        );
      } finally {
        wipeBytes(password);
        wipeBytes(dek);
        wipeBytes(decoded?.vaultKey);
        wipeBytes(decoded?.sqliteBytes);
      }
    },
  );
}
